#!/usr/bin/env python3
"""Generate Batch 8 SEO MDX posts.

Delegates body + FAQ synthesis to ``content_lib.render_post_from_spec`` so each
article is built from its own facts (table + description) and passes a pre-save
duplication guard, instead of the old shared SENTENCE_POOL + templated FAQ.
"""
from __future__ import annotations

import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
POSTS = ROOT / "content/posts"
sys.path.insert(0, str(Path(__file__).resolve().parent))

from content_lib import render_post_from_spec  # noqa: E402

CTAS = [
    "Map your next move with [Relova](https://relova.ai) so visas, housing, and money flows stay in one coherent plan.",
    "Build a relocation timeline tailored to your passport and income at [Relova](https://relova.ai).",
    "Stress-test your move before you book flights using [Relova](https://relova.ai).",
    "Turn research into a checklist you can execute week by week with [Relova](https://relova.ai).",
    "Start your personalized relocation plan today at [Relova](https://relova.ai).",
]


def slugify(text: str) -> str:
    s = text.lower()
    s = re.sub(r"[^a-z0-9\s-]", "", s)
    s = re.sub(r"\s+", "-", s).strip("-")
    return s

def make_desc(kw: str, rest: str) -> str:
    base = f"{kw}: {rest}".strip()
    if len(base) > 160:
        base = base[:157].rstrip(" ,;:") + "…"
    while len(base) < 150:
        base += " Verify official sources."
    if len(base) > 160:
        base = base[:157].rstrip(" ,;:") + "…"
    return base


def write_post(i, title, slug, date, kw, desc_rest, links, intro, table_md):
    desc = make_desc(kw, desc_rest)
    mdx = render_post_from_spec(
        title=title,
        slug=slug,
        date=date,
        kw=kw,
        description=desc,
        links=links,
        intro=intro,
        table_md=table_md,
        cta=CTAS[i % len(CTAS)],
    )
    (POSTS / f"{slug}.mdx").write_text(mdx, encoding="utf-8")

